    /**
     * Danh sách tất cả phiên bản
     * @return \think\Response
     * @author wuhaotian
     * @email 442384644@qq.com
     * @date 2026/2/25
     */
    public function upgradeList()
    {
        return app('json')->success($this->services->getUpgradeList());
    }

    /**
